WITH latest_match AS (SELECT s.*, top1.salary FROM departments s LEFT JOIN LATERAL (SELECT c.salary FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, dept_name, location, budget, CASE WHEN location RLIKE '^(Berlin|New York)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS location_zone FROM latest_match ORDER BY location_zone DESC NULLS LAST, location DESC
